'use strict';

const assert = require('node:assert/strict');
const createMessageBus = require('./solution');

assert.equal(typeof createMessageBus, 'function');
assert.equal(createMessageBus.name, 'createMessageBus');

const empty = createMessageBus();
assert.deepEqual(Object.keys(empty).sort(), ['publish', 'subscribe']);
assert.equal(empty.publish('nothing'), 0);
for (const value of [null, {}, 'listener', 1]) {
  assert.throws(() => empty.subscribe(value), TypeError);
}

const bus = createMessageBus();
const calls = [];
let unsubscribeSecond;
let added = false;
const first = (value) => {
  calls.push(['first', value]);
  unsubscribeSecond();
  if (!added) {
    added = true;
    bus.subscribe((laterValue) => calls.push(['late', laterValue]));
  }
};
bus.subscribe(first);
unsubscribeSecond = bus.subscribe((value) => calls.push(['second', value]));

const payload = { mutable: true };
assert.equal(bus.publish(payload), 2);
assert.strictEqual(calls[0][1], payload);
assert.strictEqual(calls[1][1], payload);
assert.deepEqual(calls.map((entry) => entry[0]), ['first', 'second']);

calls.length = 0;
assert.equal(bus.publish('next'), 2);
assert.deepEqual(calls, [['first', 'next'], ['late', 'next']]);
assert.equal(unsubscribeSecond(), undefined);
assert.equal(unsubscribeSecond(), undefined);

const throwingBus = createMessageBus();
const error = new Error('listener failed');
const order = [];
throwingBus.subscribe(() => order.push(1));
throwingBus.subscribe(() => { order.push(2); throw error; });
throwingBus.subscribe(() => order.push(3));
assert.throws(() => throwingBus.publish(42), (caught) => caught === error);
assert.deepEqual(order, [1, 2]);

const selfBus = createMessageBus();
let selfCalls = 0;
let unsubscribeSelf;
unsubscribeSelf = selfBus.subscribe(() => {
  selfCalls += 1;
  unsubscribeSelf();
});
assert.equal(selfBus.publish('a'), 1);
assert.equal(selfBus.publish('b'), 0);
assert.equal(selfCalls, 1);

